        'ms365_open_intune_import' => 'Import',
        'zabbix_blurb' => 'Overvakingsproblem opnar hendingar av seg sjølve, gjentakingar blir lagde til dei, og normaliseringar løyser dei.',
        'zabbix_intro' => 'Når Zabbix finn eit problem - ein disk som fyllest, ein server som ikkje svarar - opprettar han ei hending her, knytt til den serveren i CMDB. Viss han melder det same problemet igjen, kjem det på same sak. Når problemet er borte, blir saka løyst.',
        'zabbix_direction' => 'Zabbix kallar FreeITSM - FreeITSM koplar seg aldri til Zabbix, så han treng ikkje adressa til Zabbix eller noko Zabbix-passord. Alt Zabbix treng, står under.',
        'zabbix_not_ready' => 'Køyr System → Databaseverifisering først: han opprettar tabellen denne integrasjonen har hendingsloggen sin i.',
        'zabbix_connect' => 'Kopl til Zabbix',
        'zabbix_connect_body' => 'Zabbix sender kvart varsel til adressa under, saman med den hemmelege nøkkelen. I Zabbix går du til Alerts → Media types → Create media type, vel Webhook, gir han namnet FreeITSM, limer inn parametrane og skriptet under, og legg han så til ein brukar og til ein handling under Alerts → Actions → Trigger actions. Kryss av for «Recovery operations» i handlinga, ellers blir saker aldri løyste.',
        'zabbix_endpoint' => 'Adressa til FreeITSM (gi denne til Zabbix)',
        'zabbix_import' => 'Raskast: importer han i Zabbix',
        'zabbix_import_body' => 'Last ned mediatypen med alt utfylt - adressa over, nøkkelen din, skriptet og dei tre meldingsmalane - og gå så i Zabbix til Alerts → Media types → Import og vel fila. Etter det gir du han til ein brukar og legg til ei handling (steg 4 i rettleiinga).',
        'zabbix_import_download' => 'Last ned for Zabbix-import',
        'zabbix_import_needs_token' => 'Lag ein nøkkel først - fila inneheld han.',
        'zabbix_by_hand' => 'Eller set han opp for hand',
        'zabbix_token' => 'Nøkkel',
        'zabbix_token_none' => 'Ingen nøkkel enno - lag ein for å slå på integrasjonen.',
        'zabbix_token_make' => 'Lag nøkkel',
        'zabbix_token_rotate' => 'Ny nøkkel',
        'zabbix_rotate_confirm' => 'Lage ein ny nøkkel? Den gamle sluttar å verke med éin gong, så Zabbix feilar til du limer den nye inn i mediatypen.',
        'zabbix_params' => 'Parametrar for mediatype',
        'zabbix_params_hint' => 'Slett parametrane Zabbix fyller ut for ein ny webhook (URL, HTTPProxy, To, Subject, Message) - dei høyrer til eksempelskriptet hans, ikkje dette. Legg så til kvar linje her som ein parameter: namnet til venstre, verdien til høgre. http_proxy står tom med mindre Zabbix-serveren din berre kan nå FreeITSM gjennom ein mellomtenar. Verdiane i klammer er Zabbix-makroar - la dei stå som dei er. Linja url gir kvar sak ei lenke tilbake til problemet i Zabbix; ho krev at makroen {$ZABBIX.URL} er sett til Zabbix-nettadressa di (Zabbix: Administration → Macros). Utan han har sakene rett og slett inga lenke.',
        'zabbix_script' => 'Skript for mediatype',
        'zabbix_copy' => 'Kopier',
        'zabbix_copied' => 'Kopiert.',
        'zabbix_reach_hint' => 'Kvar Zabbix sender varsel. Han startar som den offentlege basisadressa di; viss Zabbix ligg på same server eller nettverk, kan vegen til FreeITSM vere ein annan - for Zabbix i Docker på denne maskina er det http://host.docker.internal/ og resten av stien. Endre han her, så følgjer parametrane og nedlastinga med.',
        'zabbix_tickets' => 'Hendingane han opprettar',
        'zabbix_requester' => 'Oppretta som',
