        'threecx_blurb' => 'Sjå kven som ringer før du svarar, hald kvar samtale på saka til den som ringer, og ring opp eit nummer med eitt klikk.',
        'threecx_intro' => 'Når ein samtale ringer, spør 3CX FreeITSM kven nummeret høyrer til og viser namnet til den som ringer - og opnar saka deira for analytikaren. Når samtalen er over, blir han notert på den saka, skriven av analytikaren som tok han. Telefonnummer på saker og personar kan òg ringast opp gjennom 3CX.',
        'threecx_direction' => '3CX kallar FreeITSM - FreeITSM koplar seg aldri til 3CX, så han treng ikkje adressa til telefonsystemet ditt eller noko 3CX-passord. Alt 3CX treng, ligg i malen under.',
        'threecx_not_ready' => 'Køyr System → Databaseverifisering først: han opprettar tabellen denne integrasjonen har samtaleloggen sin i.',
        'threecx_connect' => 'Kopl til 3CX',
        'threecx_connect_body' => '3CX koplar seg til FreeITSM gjennom ei CRM-mal. Lag ein nøkkel, last ned malen og last han opp i 3CX Admin Console under Integrations → CRM. 3CX må kunne nå adressa under.',
        'threecx_endpoint' => 'Adressa til FreeITSM, slik 3CX vil nå henne',
        'threecx_reach_hint' => 'Ho startar som den offentlege basisadressa di. 3CX er ofte i skya, så dette må vere ei adresse internett kan nå. Endre ho her, så følgjer nedlastinga med.',
