        'threecx_copy' => 'Kopier',
        'threecx_copied' => 'Kopiert.',
        'threecx_download' => 'Last ned',
        'threecx_download_body' => 'Malen, klar til opplasting: adressa, denne nøkkelen, oppslaget av den som ringer og samtalerapporten. Han inneheld nøkkelen, så hald fila for deg sjølv.',
        'threecx_download_needs_token' => 'Lag ein nøkkel først - malen inneheld han.',
