        'threecx_create_unknown' => 'Òg for nummer ingen i FreeITSM har',
        'threecx_create_hint' => 'Berre for innkomande samtalar (svara eller mista). Analytikaren som tok samtalen, blir tildelt. Ein ukjend som ringer blir registrert som «Caller» og nummeret, klart til å knytast til rett person.',
        'threecx_fallback' => 'Skriv notat som, når 3CX-brukaren ikkje er analytikar',
