        'threecx_dial_h' => 'Klikk for å ringe',
        'threecx_dial_body' => 'Telefonnummer på saker, på Saker → Brukarar og i Personar får ein Ring-knapp som ringer gjennom telefonen din. Han opnar på datamaskina til analytikaren sjølv, der dei alt er innlogga i 3CX, så FreeITSM treng aldri lokalnummeret deira.',
