        'tika_blurb' => 'Les teksten inni PDF-ar, eldre Office-filer og skanna dokument, slik at dei kan søkjast i.',
        'tika_intro' => 'Peikar FreeITSM mot ei teneste for dokumentlesing. Word-, Excel-, PowerPoint- og reintekst-filer blir alt søkte i utan dette; Tika legg til formata FreeITSM ikkje kan lese sjølv.',
        'tika_security_title' => 'Hald han av nettverket',
        'tika_security_body' => 'Tika har ikkje noko passord og ingen autentisering av noko slag: alt som kan nå han, vil lese kva fil han enn blir send. Køyr han slik at berre denne serveren kan snakke med han — bunden til 127.0.0.1, eller på eit privat containernettverk — og eksponer aldri porten hans mot internett.',
        'tika_connection' => 'Tilkopling',
