    'help_assistant' => [
        'heading' => 'Hjelpeassistent',
        'intro' => 'Ein assistent på kvar side som svarar på «korleis gjer eg...?» ut frå FreeITSM si eiga hjelp, på språket til kvar analytikar.',
        'no_ai_title' => 'Hjelpeassistenten fungerer utan KI.',
        'no_ai_body' => 'Utan noko oppsett søkjer han i alle hjelpesider og tek analytikarane rett til rett seksjon - gratis, umiddelbart, og ingenting forlèt serveren din.',
        'no_ai_later' => 'Legg til meir når du vil: ein <strong>embedding-nøkkel</strong> gjer han betre på laust formulerte spørsmål, og ein <strong>chat-KI</strong> skriv svaret i éi eller to setningar, på språket til den som spør - begge under.',
        'right_now' => 'Akkurat no:',
        'level_search' => 'Hjelpesøk - ingen KI sett opp',
        'level_meaning' => 'Hjelpesøk med treff etter meining - ingen chat-KI sett opp',
        'level_ask' => 'Skrivne svar frå KI, ut frå hjelpa',
        'ask_heading' => 'Skrivne svar (valfritt)',
        'ask_intro' => 'Gi assistenten ein chat-KI, så skriv han svaret i éi eller to setningar, på språket til den som spør, berre ut frå FreeITSM si hjelp - og lenkjer framleis til seksjonane han brukte. Når hjelpa ikkje dekkjer eit spørsmål, seier han frå om det, og spørsmålet blir med i Ubesvarte spørsmål.',
        'ask_cost' => 'Ein liten, rask modell er meir enn nok - han gjer berre nokre få hjelpeseksjonar om til eit kort svar. Han har sin eigen nøkkel, så kostnaden vises for seg.',
        'ask_privacy' => 'Kvart spørsmål, og hjelpeseksjonane som vart funne for det, blir sende til leverandøren du vel. Vel din eigen modellserver for å halde alt på nettverket ditt.',
        'ask_enable' => 'Skriv svar med KI',
        'ask_not_ready' => 'Vel leverandør, modell og nøkkel under, og slå dette så på.',
        'try_heading' => 'Prøv han',
        'try_hint' => 'Still eit spørsmål som deg sjølv og sjå svaret - og kva KI-en fekk. Ingenting blir lagra.',
        'try_placeholder' => 'Korleis opprettar eg ei sakshandsamingsavdeling?',
        'try' => 'Spør',
        'try_given' => 'Gitt til KI-en: {list}',
        'try_searched' => 'Han søkte igjen etter: {words}',
        'try_meta' => '{model} - {ms} ms, {tin} tokens inn, {tout} ut',
        'try_search_only' => 'Ingen KI vart brukt - dette er søkesvaret ({ms} ms).',
        'named_label' => 'Registrer kven som spurde',
        'named_hint' => 'Kryss av for Registrer kven som spurde for å behalde namnet til analytikaren saman med eit spørsmål hjelpa ikkje kunne svare på - dei får beskjed om det i vindauget sitt. Fjern krysset, og spørsmålet blir framleis lagra, utan namn.',
        'unanswered_heading' => 'Ubesvarte spørsmål',
        'unanswered_intro' => 'Spørsmål hjelpeassistenten ikkje kunne svare på - ingenting funne, eller berre svake treff - med folk sine eigne ord: den beste lista som finst over hjelp det er verdt å skrive. Administratorar får eit bjellevarsel; den som spurde får det aldri.',
        'filter_new' => 'Nye',
        'filter_done' => 'Handsama',
        'filter_all' => 'Alle',
        'mark_done' => 'Ferdig',
        'reopen' => 'Opne igjen',
        'kind_none' => 'Ingenting funne',
        'kind_weak' => 'Berre svake treff',
        'closest' => 'Næraste: {title}',
        'asked_by' => 'Spurt av {name}',
        'no_name' => 'Namn ikkje registrert',
        'handled_by' => 'Handsama av {name}, {when}',
        'empty_new' => 'Ingenting ventar - alle spørsmål til no har fått svar.',
        'empty' => 'Ingenting her.',
        'vectors_heading' => 'Treff etter meining (valfritt)',
        'vectors_intro' => 'Gi assistenten ein embedding-modell, så finn han spørsmål etter kva dei tyder, ikkje berre orda som er brukte - slik at «sjefen min vil ha ein vekentleg PDF» finn Rapportpakkar. På testspørsmåla han er målt mot, gjekk laust formulerte spørsmål frå 2 av 6 besvarte til 6 av 6.',
        'vectors_cost' => 'Å bygge vektorane kostar omtrent ei krone hos OpenAI, og kvart spørsmål etterpå ein liten brøkdel av det. Han har sin eigen nøkkel, så kostnaden vises for seg.',
        'vectors_privacy' => 'Kvart spørsmål blir sendt til leverandøren du vel, for å bli gjort om til ein vektor. Vel din eigen modellserver for å halde alt på nettverket ditt.',
        'vectors_enable' => 'Finn spørsmål etter meining',
