    'status_portal' => [
        'heading' => 'Tenestestatus på portalen',
        'intro' => 'Sluttbrukarar ser alt kva tenester som er friske, i sjølvbetjeningsportalen. Dette avgjer om dei òg ser <strong>hendingane</strong> bak ein driftsstans, og oppdateringane teamet ditt har merkt som eksterne.',
        'warning' => '<strong>Les dette før du slår det på.</strong> Hendingstitlar blei skrivne for teamet ditt, ikkje for kundar &mdash; sjekk kva dine seier før sluttbrukarar byrjar å lese dei. Berre oppdateringar som er uttrykkeleg merkte <strong>eksterne</strong>, blir nokosinne viste; alt som var skrive før denne funksjonen fanst, er internt, og held fram med å vere internt.',
