        'virt_detail' => 'Inneheld ei live-migrering, ein VM som ikkje lenger er sett, ei identitetsendring som skal gjennomgåast, ein KE med same namn som skal stadfestast, to postar for same maskin som skal slåast saman, og to ressursar for «Opprett knytt KE». Proxmox- og Cloud Director-tilkoplingane er slåtte av, så ingenting prøver å nå dei.',
