        'subtitle' => 'Slå på HTTPS for FreeITSM som køyrer i Docker',
        'not_container' => 'Denne sida er for FreeITSM som køyrer i Docker-biletet sitt, og denne installasjonen gjer ikkje det. Set opp HTTPS i vevtenaren din (Apache, IIS eller nginx) i staden.',
