        'host_help' => 'Til dømes freeitsm.internal. Eit namn som sluttar på .internal er trygt å bruke inne i eit firmanettverk. Unngå .local, som somme PC-ar reserverer til andre ting.',
        'ip_label' => 'IP-adresse til tenaren',
