        'local_warning' => 'Namn som sluttar på .local kan kome i konflikt med andre einingar på nettverket. Vurder .internal i staden.',
        'confirm_new_ca' => 'Viss du endrar namnet eller IP-adressa, blir det laga eit nytt autoritetssertifikat. Kvar PC som stolte på det gamle, må få det nye installert. Hald fram?',
        'err_invalid_host' => 'Det er ikkje eit gyldig namn. Bruk berre bokstavar, tal, bindestrekar og punktum, til dømes freeitsm.internal.',
