        'steps_heading' => 'Kva du gjer vidare',
        'step_dns_title' => 'Peik namnet mot tenaren',
        'step_dns_body' => 'PC-ane må vite at {host} tyder {ip}. Den beste måten er ei DNS-oppføring på DNS-tenaren i nettverket ditt (på eit Windows-domene i DNS Manager, på eit lite nettverk ofte i ruteren):',
        'step_dns_record' => 'Type A, namn {host}, adresse {ip}',
