        'step_dns_no_ip' => 'Fyll ut IP-adressa til tenaren ovanfor for å sjå nøyaktig kva oppføring du skal lage.',
        'step_ca_title' => 'Installer autoritetssertifikatet på kvar PC',
        'step_ca_body' => 'Dette får PC-ane til å stole på sertifikatet. Det treng berre gjerast éin gong per PC, og igjen berre viss du endrar namnet eller IP-adressa.',
        'download' => 'Last ned',
        'step_ca_windows' => 'Windows: dobbeltklikk på fila, vel Install Certificate, vel Local Machine, så Place all certificates in the following store, og vel Trusted Root Certification Authorities.',
        'step_ca_gpo' => 'Mange Windows-PC-ar på eit domene: importer fila éin gong i Group Policy, under Computer Configuration → Policies → Windows Settings → Security Settings → Public Key Policies → Trusted Root Certification Authorities. Intune kan sende henne ut som ein Trusted certificate-profil.',
        'step_ca_mac' => 'Mac: dobbeltklikk på fila for å leggje henne til i Keychain Access, opne henne der, og set When using this certificate til Always Trust.',
        'step_ca_firefox' => 'Firefox på Windows bruker Windows-sertifikata automatisk. Viss han framleis åtvarar, set security.enterprise_roots.enabled til true i about:config.',
        'step_ca_safe' => 'Denne autoriteten kan berre gå god for {host}, ingenting anna, så å installere han let han ikkje utgje seg for å vere nokon annan nettstad.',
        'step_restart_title' => 'Start containeren på nytt',
        'step_restart_body' => 'Køyr {cmd} i mappa som inneheld docker-compose.yml.',
        'step_restart_done' => 'Ferdig: containeren bruker dette sertifikatet.',
        'step_open_title' => 'Opne FreeITSM over HTTPS',
        'step_open_body' => 'Gå til {url}. Viss han ikkje lastar, sjekk at docker-compose.yml publiserer port 443 (standardfila knyter han til 8443). Viss du har endra det, bruk porten din i staden.',
        'proxy_heading' => 'Bak ein reverse proxy',
        'proxy_intro' => 'Viss ein reverse proxy, lastbalanserar eller Cloudflare Tunnel står føre FreeITSM, kjem kvar førespurnad til FreeITSM frå proxyen. Med mindre du seier til FreeITSM kva adresse som er proxyen, registrerer han adressa til proxyen for alle: i Rapportar → Loggar, i revisjonsspora, og når ein API-nøkkel sjekkar kva adresser han tillèt.',
        'proxy_off_title' => 'Av',
        'proxy_off_body' => 'FreeITSM registrerer adressa kvar tilkopling kjem frå. Det er rett når folk koplar rett til FreeITSM, og gale bak ein proxy - bruk Test under for å sjå kva du har.',
        'proxy_on_title' => 'På',
        'proxy_on_body' => 'Den ekte adressa blir henta frå {header}-headeren, men berre på førespurnader som kjem frå {list}.',
        'proxy_refused_title' => 'Sett, men ikkje i kraft',
        'proxy_refused_body' => 'TRUSTED_PROXIES er sett til {list}, men han vart avvist då containaren starta, så FreeITSM registrerer adressa kvar tilkopling kjem frå. Køyr {cmd} for å sjå kvifor.',
        'proxy_wide_title' => 'Åtvaring: denne innstillinga er for vid',
        'proxy_wide_body' => '{ranges} dekkjer meir enn éin proxy. Kvar maskin i han kan påstå å vere kva adresse han vil. Endre TRUSTED_PROXIES til proxyen si eiga adresse og start containaren på nytt.',
        'proxy_danger_title' => 'Kva ei feil innstilling gjer - les dette før du endrar',
        'proxy_danger_wide' => 'For vid - den farlege feilen. FreeITSM trur på adressa i headeren frå proxyen berre på førespurnader frå adressene du listar, fordi kven som helst kan skrive den headeren. List du eit område som {example} eller heile Docker-nettverket, kan kvar maskin i det påstå å vere kva adresse som helst: han kan setje ei falsk adresse i innloggingsloggen og revisjonsspora, og kome forbi ein API-nøkkel som berre tillèt visse adresser. List berre proxyen si eiga adresse.',
        'proxy_danger_missing' => 'Ikkje sett, når det finst ein proxy. Ingenting går i stykke, men kvar innlogging og kvar endring blir registrert frå adressa til proxyen, så loggane kan ikkje skilje folk frå kvarandre - og dei tillatne adressene til ein API-nøkkel kan berre nemne proxyen, noko som slepp inn kven som helst som kjem gjennom han.',
        'proxy_danger_wrong' => 'Feil adresse. Headeren blir ignorert, så du er tilbake til at alle blir registrerte som proxyen. Test viser dette med ein gong.',
        'proxy_how' => 'Dette blir sett i docker-compose.yml, ikkje på denne sida, og tek effekt når containaren startar på nytt (docker compose up -d):',
        'proxy_how_cf' => 'For ein Cloudflare Tunnel, set òg {setting}. Fleire proxyar: skil dei med mellomrom.',
        'proxy_test_heading' => 'Test.',
        'proxy_test_intro' => 'Viser adressa FreeITSM nett registrerte for deg, og kva ho tyder. Han endrar ingenting.',
        'proxy_test' => 'Test',
        'proxy_testing' => 'Testar...',
        'proxy_test_failed' => 'Testen kunne ikkje køyrast.',
        'proxy_recorded' => 'FreeITSM registrerte adressa di som',
        'verdict_direct' => 'Du koplar rett til FreeITSM - ingen proxy-header kom - så det er ingenting å setje. Viss du veit at det står ein proxy føre, legg han ikkje til nokon header: sjekk innstillingane hans.',
        'verdict_off_proxy' => 'Ein proxy står føre FreeITSM (denne førespurnaden bar {headers}), og FreeITSM registrerer adressa til proxyen, {ip}, for alle. For å registrere ekte adresser, legg dette til i miljøet til appen i docker-compose.yml:',
        'proxy_suggest_then' => 'Det er adressa til proxyen slik FreeITSM ser henne - list henne åleine, ikkje noko breiare. Køyr så docker compose up -d og test igjen.',
        'verdict_working' => 'Fungerer: denne adressa kom frå headeren til proxyen. Sjekk at ho verkeleg er adressa til datamaskina di - på Windows viser ipconfig henne; utanfor nettverket ditt, den offentlege adressa di. Viss ho viser adressa til proxyen eller 127.0.0.1, er noko gale.',
