        'inbound_heading' => 'Endringar gjorde i kalenderen',
        'inbound_desc' => 'Flytt ein av desse avtalane i Outlook, og saka følgjer med. Dette krev at jobben <code>cron/calendar_sync_pull.php</code> køyrer &mdash; kvart 5. minutt er fornuftig. Utan han er synkroniseringa einvegs, som er akkurat slik ho fungerer i dag.',
        'accept_deletes' => 'Å slette avtalen fjernar planlegginga av saka',
        'notify_url' => 'Varslings-URL (valfritt)',
        'notify_url_note' => 'Lat stå tomt for å stole på den planlagde sjekken åleine, som er heilt god &mdash; endringar kjem då inn i løpet av nokre minutt. Fyll han ut, og Microsoft vil fortelje FreeITSM i det augeblikket noko endrar seg, så det landar på sekund. Det må vere ei <strong>HTTPS-adresse Microsoft kan nå frå internett</strong>, som endar på <code>/api/calendar/graph_notify.php</code>. Den planlagde jobben er framleis påkravd uansett: han fornyar abonnementa, og han fangar opp alt eit tapt varsel elles ville mista.',
        'notify_suggest' => 'Bruk denne adressa',
