        'health_never' => 'Kalendrane har aldri blitt sjekka.',
        'health_stale_note' => 'Endringar gjorde i Outlook kjem inn når den planlagde jobben køyrer, så dette tyder som oftast at han har stoppa &mdash; sjekk at <code>cron/calendar_sync_pull.php</code> framleis køyrer etter tidsplanen sin. Det er òg han som fornyar abonnementa, så varsel stoppar nokre dagar etter at han gjer det. Viss du med vilje køyrer han sjeldnare enn kvar halvtime, er dette venta.',
