        'sub_none' => 'Ikkje abonnert',
        'sub_none_note' => 'Ei varslingsadresse er sett, men Microsoft har ingenting å kalle for denne personen, så endringane deira kjem berre inn når den planlagde jobben køyrer. Neste køyring vil prøve å opprette ho; viss det held fram med å feile, dukkar grunnen opp her.',
        'sub_lapsed' => 'Abonnementet har gått ut',
        'accept_deletes_note' => 'Av som standard. Med det på finn ein analytikar som slettar ein av desse på telefonen sin, saka alt fjerna frå planlegginga når dei set seg ned &mdash; som ofte er poenget. Kvar slik endring vert skriven til saka sin historikk, og eit uvanleg stort tal slettingar på éin gong vert nekta i staden for utført, sidan det er meir sannsynleg ein feil enn ein instruksjon. Med det av dukkar ein sletta avtale rett og slett opp igjen neste gong saka endrar seg.',
