        'nt_company_heading' => 'Selskapet mitt for nye saker',
        'nt_company_desc' => 'I visinga for alle selskap spør Ny sak kva selskap ei sak er for. Vel eitt her for å få det valt for deg. Du kan framleis endre det i skjemaet, og viss du ikkje lenger har tilgang til selskapet, blir ingenting valt.',
        'nt_company_none' => 'Ingen - eg vel kvar gong',
        'search_dismiss_heading' => 'Å lukke søkjepanelet',
        'search_dismiss_desc' => 'Søkjepanelet kan dragast til side og latast stå ope, så som standard er det berre ✕-en eller Escape-tasten som lukkar det. Slå på dette for at det skal lukke seg så snart du klikkar bort — på mappelista, sakslista eller verktøylinja. Å klikke på saka du nettopp fann, eller eigenskapane hennar, held framleis panelet ope, så eit søk overlever at du handlar på resultatet.',
