        'carddav_write_warning' => 'Berre opplysningane lista opp over blir endra, og berre på kontakten som blir redigert. Alt anna på kortet — bilete, notat, fødselsdag, full adresse, grupper — blir verande akkurat som det er. Viss nokon har endra den same opplysninga i adresseboka sidan FreeITSM sist importerte, blir endringa avvist heller enn å skrive over deira.',
