    'webhooks' => [
        'browser_title' => 'Webhooks',
        'title' => 'Webhooks',
        'subtitle' => 'Utgåande webhooks &mdash; lagde i kø av arbeidsflythandlinga <em>Send ein webhook</em> &mdash; blir leverte i bakgrunnen med automatiske nye forsøk, så eit tregt eller dødt endepunkt aldri held ei sak att. Denne sida viser om levering er sett opp, ei oversikt over leveringshelsa, og heile loggen der du kan granske kvar førespurnad, svaret på han, og sende kva som helst av det på nytt.',
        'pill_running' => 'Leveringsarbeidaren køyrer',
        'pill_stale' => 'Leveringsarbeidaren er forseinka',
        'pill_down' => 'Leveringsarbeidaren har stoppa',
        'pill_never' => 'Ikkje sett opp enno',
        'last_ran' => 'Køyrde sist {when}',
        'running_ok' => 'Bakgrunnsarbeidaren køyrer og leverer køen.',
        'waiting_one' => '<strong>1</strong> webhook ventar &mdash; han går ut innan eit minutt.',
        'waiting_many' => '<strong>{n}</strong> webhooks ventar &mdash; dei går ut innan eit minutt.',
        'nothing_waiting' => 'Ingenting ventar akkurat no.',
        'never_explain' => '<strong>Webhooks blir ikkje sende</strong> før bakgrunnsarbeidaren for levering er sett opp til å køyre.',
        'down_explain' => '<strong>Webhooks blir ikkje sende lenger</strong> &mdash; arbeidaren køyrde sist {when} og ser ut til å ha stoppa.',
        'stale_explain' => 'Arbeidaren køyrer, men ligg etter planen (køyrde sist {when}). Han bør køyre kvart minutt.',
        'queued_one' => '<strong>1</strong> webhook ligg i kø og ventar.',
        'queued_many' => '<strong>{n}</strong> webhooks ligg i kø og ventar.',
        'step1' => '<strong>Set opp leveringsarbeidaren til å køyre kvart minutt.</strong> På tenaren køyrer du denne kommandoen frå ei planlagd oppgåve (Windows Task Scheduler) eller cron (Linux):',
        'step1_http' => 'Får du ikkje køyrt PHP frå skalet? Kall det over HTTP i staden (t.d. frå ei cron-teneste i skya):',
        'step2' => '<strong>Legg handlinga <em>Send ein webhook</em> til i ein arbeidsflyt</strong> så hendingar byrjar å fylle køen &mdash; under <a href="{url}">Arbeidsflytar</a>.',
        'step3' => '<strong>Følg med på denne sida.</strong> Så snart arbeidaren køyrer, blir statusen over grøn og leveringane dukkar opp nedanfor. Fullstendige oppsettnotat (Windows &amp; Linux, kontroll av signatur) finst i <a href="https://github.com/edmozley/freeitsm/wiki/Workflows" target="_blank" rel="noopener">Workflows-wikien</a>.',
        'fact_worker' => 'Arbeidarskript',
        'fact_retry' => 'Plan for nye forsøk',
        'fact_retry_sched' => '{schedule} &middot; død etter {n} forsøk',
        'fact_retry_once' => 'Ingen nye forsøk &middot; død etter 1 forsøk',
        'fact_retention' => 'Lagringstid for loggen',
        'fact_queued' => 'I kø no',
        'days' => '{n} dagar',
        'del_title' => 'Levering',
        'del_desc' => 'Kor hardt FreeITSM prøver å få kvar webhook igjennom.',
        'opt_default' => '{label} (standard)',
        'del_attempts_label' => 'Forsøk før han gir opp',
        'del_attempts_one' => '1 forsøk (ingen nye forsøk)',
        'del_attempts_opt' => '{n} forsøk',
        'del_attempts_help' => 'Eit mislukka forsøk blir prøvd på nytt etter 1 minutt, så 5 minutt, 15 minutt, 1 time og 6 timar, og deretter kvar sjette time. Etter det siste forsøket blir leveringa merkt <strong>Død</strong> og ventar på <em>Spel av igjen</em>. Ei endring gjeld for webhooks som blir køa frå no av - dei som alt er i køa, behald talet dei starta med.',
        'del_timeout_label' => 'Vent på at endepunktet svarer',
        'del_timeout_opt' => '{n} sekund',
        'del_timeout_help' => 'Kor lenge kvart forsøk ventar før det tel som mislukka. Auk det berre for eit endepunkt som er kjent for å vere tregt: arbeidaren sender éin webhook om gongen, så ei lang venting held opp resten av køen. <em>Send test</em> i arbeidsflytredigeraren ventar høgst 25 sekund.',
        'del_int_label' => 'Viss ei sending vart broten av midt i',
        'del_int_retry' => 'Prøv igjen - endepunktet kan få henne to gonger',
        'del_int_stop' => 'Stopp, og la henne liggje for Spel av igjen',
        'del_int_help' => 'Viss arbeidaren blir stoppa midt i ei sending - ei omstart av tenaren, eller at den planlagde oppgåva blir avslutta - veit ingen om endepunktet fekk ho. Etter 10 minutt avgjer FreeITSM saka: <strong>Prøv igjen</strong> tel ho som eit mislukka forsøk og prøver på nytt etter planen ovanfor; <strong>Stopp</strong> merkjer ho Død med éin gong, så du kan sjekke endepunktet og spele ho av igjen sjølv. Kvar sending har ein <code>X-FreeITSM-Delivery</code>-header med same tal for kvart forsøk og for ei avspeling, så ein mottakar du køyrer sjølv kan ignorere ei gjentaking. Nettprat-verktøy som Slack og Teams kan ikkje det, og ville vist meldinga to gonger.',
        'dp_title' => 'Datavern',
        'dp_desc' => 'Kva FreeITSM tek vare på på disk om webhookane dine, og kor lenge.',
        'enc_on_title' => 'Webhook-URL-ar og signeringsnøklar er krypterte i kvile',
        'enc_on_body' => 'Lagra med AES-256-GCM, både i arbeidsflyten og i leveringskøen. Ein webhook-URL er ein legitimasjon i seg sjølv &mdash; alle som har han, kan poste til kanalen din &mdash; og signeringsnøkkelen er det som viser at ei melding verkeleg kom frå deg.',
        'enc_off_title' => 'Ingen krypteringsnøkkel er sett opp &mdash; webhook-URL-ar og signeringsnøklar blir lagra i klartekst',
        'enc_off_body' => 'FreeITSM krypterer desse når det finst ei krypteringsnøkkelfil, men denne installasjonen har ingen, så dei blir lagra som dei er i staden for at webhookane dine feilar heilt. Alle som kan lese databasen eller ein tryggingskopi av han, kan poste til kanalane dine og forfalske signaturane dine. Set opp krypteringsnøkkelen (<code>ENCRYPTION_KEY_PATH</code>) og lagre kvar webhook-arbeidsflyt på nytt for å kryptere dei lagra verdiane.',
        'ret_label' => 'Ta vare på sende nyttelaster i',
        'ret_none' => 'Ikkje lagre dei i det heile',
        'ret_1' => '1 dag',
        'ret_7' => '7 dagar (tilrådd)',
        'ret_30' => '30 dagar',
        'ret_forever' => 'Så lenge leveringsposten varer',
        'ret_help' => 'Leveringsloggen lagrar nøyaktig den nyttelasta som vart sendt. Med formatet <strong>Full post</strong> er det <strong>ei heil sak</strong> &mdash; emne, bestillar, alt saman &mdash; kopiert hit i klartekst. Etter så mange dagar blir nyttelasta og svarinnhaldet vaska bort, medan sjølve <em>leveringsposten</em> (endepunkt, status, tidsbruk, feil) blir teken vare på for revisjon til lagringstida over ({days} dagar) fjernar rada heilt.',
        'ret_tradeoff' => '<strong>Avveging:</strong> <em>Send på nytt</em> sender den lagra nyttelasta om att, så ei levering der nyttelasta er vaska bort, kan ikkje sendast på nytt lenger. Send på nytt blir normalt brukt timar etter ein feil, ikkje veker.',
        'ov_title' => 'Oversikt',
