    'managers' => [
        'heading' => 'Leiarar',
        'intro' => 'Ein leiar er ein person i sjølvbetjeningsportalen som kan sjå sakene som er oppretta av dei dei er leiar for - til dømes avdelingssjefen. Dei får ei <strong>Teamsaker</strong>-fane i portalen. Servicedesken blir ikkje påverka.',
        'needs_verify' => 'Køyr System → Databaseverifisering først. Fram til han har køyrt, er leiarar slått av uansett kva som er sett her, fordi fortrulege saker ikkje kunne skiljast frå andre.',
        'on_heading' => 'Leiarar i portalen',
        'enabled' => 'La leiarar sjå sakene til teamet sitt',
        'enabled_desc' => 'Av til du slår det på. Ingenting nedanfor har noko å seie så lenge dette er av.',
        'source_heading' => 'Kvar leiarane kjem frå',
        'source_desc' => 'To kjelder, begge samtidig. Leiarlinjer blir sette opp for kvar leiar med knappen Leiartilgang under Saker → Brukarar eller Ressursar → Brukarar.',
        'directory' => 'Bruk Leiar-feltet til kvar person',
        'directory_desc' => 'Den som er sett som leiar for nokon - for hand, eller frå katalogen din - kan sjå sakene deira.',
        'depth' => 'Kor langt ned',
        'depth_direct' => 'Dei som rapporterer direkte til dei',
        'depth_all' => 'Alle under dei, heilt ned',
        'can_heading' => 'Kva leiarar kan gjere',
        'can_desc' => 'Leiarar kan alltid lese sakene til teamet sitt. Dei får beskjed på kvar sak om kva dei elles kan gjere.',
        'can_reply' => 'Svare på sakene til teamet sitt',
        'can_close' => 'Lukke sakene til teamet sitt',
        'conf_heading' => 'Fortrulege saker',
        'conf_desc' => 'Kva ein leiar ser av ei sak som er merkt fortruleg - ei diagnose sendt til HR, eller ei klage på leiaren sjølv.',
        'conf_none' => 'Ingenting i det heile (tilrådd)',
        'conf_none_desc' => 'Saka blir utelaten heilt. Ein leiar kan ikkje ein gong sjå at ho finst.',
        'conf_stub' => 'At ei fortruleg sak finst',
        'conf_stub_desc' => 'Blir lista som «Fortruleg sak» med nummer og status, og ingenting av det ho seier. Vit at dette åleine kan fortelje ein leiar at nokon har tatt opp noko privat.',
        'conf_all' => 'Alt',
        'conf_all_desc' => 'Fortrulege saker blir viste som alle andre. Vel dette berre viss ingenting fortruleg nokon gong blir tatt opp via denne portalen.',
        'notify_heading' => 'Varsle leiarar om nye saker',
        'notify_desc' => 'Når nokon på teamet til ein leiar opprettar ei sak - men aldri ei som leiaren ikkje har lov til å opne, som ei fortruleg sak.',
        'notify_none' => 'Ikkje varsle (standard)',
        'notify_none_desc' => 'Leiarar ser nye saker når dei ser på Teamsaker.',
        'notify_email' => 'Send dei e-post',
        'notify_email_desc' => 'Ein e-post med sakas nummer og emne og ei lenke til henne, sendt til adressa til leiaren frå sakspostkassa. Leiarar utan adresse får ingenting. Lenka krev den offentlege vevadressa (Saker → Innstillingar → E-postmalar) - utan ho sender ei sak som kjem inn på e-post ei lenke som ikkje fungerer.',
        'notify_bell' => 'I varselklokka i portalen',
        'notify_bell_desc' => 'Inn i klokka kvar leiar har i portalhovudet - den same klokka analytikarar har. Roleg enn e-post: ho ligg der neste gong dei loggar inn.',
        'leavers_heading' => 'Folk som har slutta',
        'leavers' => 'Fortset å vise sakene til folk som har slutta',
        'leavers_desc' => 'På som standard, så ei sak som framleis er open når nokon sluttar, beheld tilsynet. Ein leiar som har slutta, mistar alltid tilgangen.',
        'edit_heading' => 'Kven som kan setje opp leiarlinjer',
