    'self_service' => [
        'heading' => 'Sjølvbetjeningsportal',
        'intro' => 'Korleis portalen ser ut for dei som melder saker, og kva han lèt dei gjere. For dei fleste organisasjonar er portalen den einaste delen av FreeITSM ein kunde nokon gong ser, så det er den eine skjermen det er verdt å merkevarebyggje for seg.',
        'appearance_heading' => 'Utsjånad',
        'appearance_desc' => 'Desse gjeld berre portalen. Logoen under <strong>System &rarr; Merkevare</strong> dekkjer framleis appen, innloggingsskjermen og e-postane dine.',
        'logo_label' => 'Portallogo',
        'logo_desc' => 'Ein annan logo for portalen &mdash; nyttig når servicedesken driv under eit anna namn, eller når hovudlogoen er teikna for ein mørk apptopp og ser feil ut på ei lys side. La feltet stå tomt for å bruke hovudlogoen.',
        'logo_remove' => 'Fjern',
        'logo_hint' => 'PNG eller JPG, opptil 2 MB. SVG blir ikkje godtatt: det er XML som kan innehalde skript, og dette biletet blir vist til alle som besøkjer portalen.',
        'logo_saved' => 'Portallogoen er oppdatert',
        'logo_position_label' => 'Kvar logoen skal stå',
